using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidStrategySelectionFileStore{private readonly string _path;public AndroidStrategySelectionFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(AndroidStrategySelection value){if(string.IsNullOrWhiteSpace(value.SelectionFingerprint))throw new InvalidOperationException("Strategy selection fingerprint is required.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public AndroidStrategySelection Load()=>JsonSerializer.Deserialize<AndroidStrategySelection>(File.ReadAllText(_path))??throw new InvalidOperationException("Strategy selection JSON is invalid.");}
